# -*- coding: utf-8 -*-
from fams import *
F = 'ad'
def ad(slug, title, h1, crumb, desc, hero, answer, cards, why, steps, faq, who):
    page(slug, F, title, desc, h1, crumb, hero, answer, cards,
         [S('What usually sits behind it', ul(why)), S('What to do', ol(steps))], faq, who)

ad('ad-account-disabled-after-billing-country-change', 'Ad Account Disabled After Billing Country Change',
 'Meta ad account disabled after you changed billing country?', 'After a billing country change',
 'Meta ad account disabled after a billing country, currency or business address change? What the system sees and how to prepare an appeal.',
 'Changing the billing country, address or business details can trip a security review.',
 'Meta can disable an ad account when the billing country, business address or payment details change suddenly, because it looks like a takeover. Gather proof that the new country is real: a registration, a utility bill or lease, and the business site. Then appeal in Account Quality, once, with the same details in every field.',
 [('Match every field', 'Business address, billing country and website should agree.'),
  ('Prove the move', 'Registration or lease for the new country.'),
  ('Appeal once', 'Several appeals in a row can make it worse.')],
 ['A payment method from a different country than the account.', 'A change of business address with no supporting documents.', 'A business portfolio set up in one country and billed in another.', 'A recent login from a place that does not match the billing details.'],
 ['Open Account Quality and copy the notice.', 'Prepare proof of the new country: registration, lease or utility bill.', 'Make the business details match on the portfolio, ad account and Page.', 'Submit one appeal that explains the change plainly.'],
 [('Can I switch back?', 'Changing details again and again can look worse. Explain the real situation.'),
  ('Does a VPN matter?', 'Yes. Log in from the usual place and avoid VPNs while appealing.'),
  ('Do the ads keep running?', 'They stop while the account is disabled.')],
 ['Businesses that moved country.', 'Founders who changed their billing setup.', 'Agencies re-assigning an account.'])

ad('ad-account-disabled-pixel-or-conversions-api-misuse', 'Ad Account Disabled for Pixel or Conversions API Misuse',
 'Meta ad account disabled over pixel or Conversions API data?', 'Pixel or Conversions API flag',
 'Meta ad account disabled over pixel or Conversions API data, such as sensitive events? What triggers it and what to fix before you appeal.',
 'Sending sensitive customer data through the pixel is a common but little-known cause.',
 'Meta restricts accounts that send sensitive data through the pixel or the Conversions API, such as health details, financial status or other personal information in event names and parameters. Check which events your site sends, remove the sensitive ones, and then appeal with a short note describing the correction.',
 [('Audit the events', 'List every event and parameter your site sends.'),
  ('Remove sensitive fields', 'No health, finance or personal identifiers in names.'),
  ('Appeal after the fix', 'Say what you changed.')],
 ['Event names that reveal health or financial conditions.', 'URL parameters that include personal details.', 'A third-party plugin sending more data than expected.', 'Data from a site that serves a restricted category.'],
 ['Open Events Manager and check the events and parameters.', 'Disable or rename any that reveal sensitive details.', 'Check plugins and tag managers that send data.', 'Submit an appeal that names the fix.'],
 [('Is the data policy different from ad policy?', 'Yes. Data rules cover what you send. Ad rules cover the creative.'),
  ('Does this affect the pixel only?', 'It can also limit the ad account.'),
  ('Can I keep the pixel installed?', 'Yes, once the data it sends is compliant.')],
 ['Health, finance and legal sites.', 'Stores with custom tracking.', 'Agencies managing tracking setups.'])

ad('ad-account-restricted-financial-products-and-services-ads', 'Ad Account Restricted for Financial Ads',
 'Meta ad account restricted for financial products and services?', 'Financial products and services',
 'Meta restricted your ads for financial products and services? Authorisation, special ad category and wording issues, and what to prepare.',
 'Loans, investing, insurance and similar offers sit under extra rules, and many advertisers miss them.',
 'Ads for loans, investing, insurance and other financial products need the special ad category and, in some countries, authorisation to advertise. If your ad account was restricted, check whether your offer falls under that category, whether the targeting is limited as required, and whether your site shows licence details. Then appeal.',
 [('Pick the right category', 'Credit, financial products and services.'),
  ('Check authorisation', 'Some countries need it before you run.'),
  ('Show licence details', 'On the landing page where required.')],
 ['The special ad category was not selected.', 'Targeting options that are not allowed for this category.', 'Missing licence or disclosure information on the site.', 'Claims about returns that are too specific.'],
 ['Read the notice and note which rule is named.', 'Set the correct special ad category on new campaigns.', 'Add licence and disclosure details to the landing page.', 'Appeal once with the changes listed.'],
 [('Does this apply to a broker?', 'It can. The test is the product or service offered.'),
  ('Can I appeal if I am licensed?', 'Yes. Licence details strengthen the appeal.'),
  ('Do these rules vary by country?', 'Yes. Check the requirements for each country you target.')],
 ['Finance and insurance businesses.', 'Advisers and brokers.', 'Fintech startups.'])

ad('ad-account-restricted-alcohol-or-age-restricted-ads', 'Ad Account Restricted for Alcohol or Age-Restricted Ads',
 'Meta ad account restricted over alcohol or age-restricted ads?', 'Alcohol or age-restricted ads',
 'Meta restricted your ad account for alcohol, vaping or other age-restricted products? The rules, the audience settings and how to appeal.',
 'Age-restricted products need the right audience settings and sometimes permission, depending on the country.',
 'Alcohol and other age-restricted products can be advertised in many countries, but only to an adult audience and sometimes only with local permission. Check the audience age setting, the creative and the landing page, remove anything that appeals to minors, and confirm the product is allowed where you advertise. Then appeal with those details.',
 [('Set the minimum age', 'Many countries require 18 or 21 as a minimum.'),
  ('Check the creative', 'Nothing that appeals to minors or promotes excess.'),
  ('Check the country', 'Local law decides what is allowed.')],
 ['Audience settings that include minors.', 'Creative that suggests drinking before an age limit.', 'A landing page with no age gate.', 'Targeting a country where the product cannot be advertised.'],
 ['Read the notice and note the named rule.', 'Set the right minimum age and country targeting.', 'Review the creative and landing page for the points above.', 'Appeal once, with the corrections listed.'],
 [('Is every alcohol ad banned?', 'No. Rules vary by country and product.'),
  ('Do I need written permission?', 'In some countries, yes. Check the local requirements.'),
  ('Can I promote events with alcohol?', 'Event promotion has its own rules. Read them for your country.')],
 ['Breweries and wine sellers.', 'Bars and event organisers.', 'Agencies serving these clients.'])

ad('ad-account-restricted-social-issue-ads-authorization', 'Ad Account Restricted for Social Issue Ads Authorization',
 'Meta ad account restricted until you authorise for social issue ads?', 'Social issue ads authorization',
 'Meta asks for authorisation for social issues, elections or politics ads and restricted your account? What it requires and how to prepare.',
 'Ads about social issues, elections or politics need an authorisation step, and ads without it can be rejected or restricted.',
 'If your ads touch social issues, elections or politics, Meta requires identity confirmation and a disclaimer showing who paid. If your account was restricted for running these ads without authorisation, complete the identity step, add the disclaimer, and check whether your ad really belongs to that category. If it does not, appeal and explain.',
 [('Check the category', 'Is the ad really about a social issue?'),
  ('Confirm your identity', 'The advertiser must be verified.'),
  ('Add the disclaimer', 'It shows who paid for the ad.')],
 ['Ads that mention a political topic, even lightly.', 'Missing identity confirmation for the person or business.', 'A missing disclaimer on the ad.', 'Ads in a country with extra requirements.'],
 ['Read the notice and see which topic is named.', 'Complete identity confirmation if the ad belongs in the category.', 'Add the disclaimer and use the correct category.', 'If the ad does not belong in it, appeal with a clear explanation.'],
 [('Does my business need this?', 'Only if your ads are about social issues, elections or politics.'),
  ('Who must confirm identity?', 'The person who runs the ads, using valid documents.'),
  ('Can an agency do it for me?', 'The advertiser still has to be authorised in their own name.')],
 ['Nonprofits and advocacy groups.', 'Publishers and media businesses.', 'Agencies running campaigns for them.'])

ad('ad-account-disabled-lead-form-complaints', 'Ad Account Disabled After Lead Form Complaints',
 'Meta ad account disabled after lead form complaints?', 'Lead form complaints',
 'Meta ad account disabled after complaints about lead ads or instant forms? Why lead ads attract reports and how to appeal.',
 'Lead ads that ask too much, or that mislead about what happens next, attract user reports.',
 'Lead forms attract reports when they ask for sensitive information, when the promise in the ad does not match the form, or when people are contacted in ways they did not expect. If your ad account was disabled after complaints, check the form fields, the privacy policy link and the follow-up process, fix what is off, and appeal.',
 [('Trim the form', 'Ask only what you need.'),
  ('Match the ad to the form', 'No promises the form cannot keep.'),
  ('Check follow-up', 'People should hear from you as the form said.')],
 ['Sensitive questions in the form.', 'An ad that suggests an offer the form does not give.', 'Missing or broken privacy policy link.', 'Follow-up contact that surprised people.'],
 ['Open the form and review each field.', 'Check the privacy policy link and the thank-you message.', 'Make sure the ad and the form say the same thing.', 'Appeal with the corrections listed.'],
 [('Can the form be edited?', 'Yes. Edit it before appealing.'),
  ('Do I need to delete leads?', 'No. Handle them as the form said.'),
  ('Will complaints be shown to me?', 'Not usually. The notice gives the policy, not the complainant.')],
 ['Local service businesses.', 'Real estate and education.', 'Agencies running lead campaigns.'])

ad('ad-account-business-portfolio-verification-failed', 'Business Portfolio Verification Failed for Meta Ads',
 'Business verification for your Meta business portfolio failed?', 'Business verification failed',
 'Meta business portfolio verification failed or is stuck? The documents that match, name and address mismatches, and how to retry cleanly.',
 'Most failures are mismatches between the documents, the portfolio name and the website.',
 'Business verification fails when the legal name, address or phone on your documents does not match the portfolio or the website, or when the documents are unclear. Make the portfolio details match your registration exactly, use a current document, and make sure the website shows the same business name. Then submit again once, not repeatedly.',
 [('Match the legal name', 'Exactly as on the registration.'),
  ('Use a clear document', 'Current, readable and complete.'),
  ('Align the website', 'It should show the same name and contact details.')],
 ['A legal name that differs from the portfolio name.', 'A document that is old, cropped or unreadable.', 'A website with no business details.', 'A domain that does not match the business.'],
 ['Compare the portfolio details with the registration line by line.', 'Update the portfolio and website where they differ.', 'Upload a clear, current document.', 'Submit once and wait for the result before trying again.'],
 [('Can I use a utility bill?', 'In some countries yes. The form lists accepted documents.'),
  ('Does verification affect ads?', 'It can limit ad features and the spending cap.'),
  ('Does a trading name matter?', 'Use the legal name, and list the trading name where asked.')],
 ['New businesses setting up a portfolio.', 'Agencies verifying a client.', 'Companies with a recent name change.'])

ad('ad-account-disabled-domain-verification-problem', 'Ad Account Disabled After a Domain Verification Problem',
 'Meta ad account in trouble after a domain verification problem?', 'Domain verification problem',
 'Meta ad account limited after domain verification failed, or after a domain change or a flagged domain? What to check and how to appeal.',
 'Domains drive ad approval. A flagged or mismatched domain can limit the account.',
 'Meta ties ad approval and tracking to your verified domain. A domain that fails verification, changed recently, looks unsafe or does not match the business can lead to restrictions. Check that the domain records are correct, that the site has a clear business identity and policy pages, and that nothing on it is flagged. Then appeal with details.',
 [('Check the records', 'The verification record must still be in place.'),
  ('Check the site', 'Business identity and policy pages visible.'),
  ('Check for flags', 'Scan for malware or blocked-domain notices.')],
 ['A removed or changed verification record.', 'A new domain with no history and little content.', 'A site flagged as unsafe.', 'A redirect to a different domain than the one in the ad.'],
 ['Check the verification record in your DNS or site files.', 'Add clear business details and policy pages to the site.', 'Check for malware or blocked-domain warnings.', 'Appeal, listing what you fixed.'],
 [('Do I need to re-verify?', 'If the record is gone, yes.'),
  ('Does the domain have to match the Page?', 'It helps. Inconsistent branding raises questions.'),
  ('Is this the same as a landing page problem?', 'Related, but the domain check is separate.')],
 ['Stores that changed domain.', 'New sites running ads.', 'Agencies managing many domains.'])

ad('ad-account-disabled-after-sudden-spend-spike', 'Ad Account Disabled After a Sudden Spend Spike',
 'Meta ad account disabled after a sudden jump in spend?', 'After a sudden spend spike',
 'Meta ad account disabled after a sudden rise in spend or budget? Why it looks like a compromise and how to appeal.',
 'A large jump in budget, especially from a new account, looks like someone else is using it.',
 'A sudden jump in budget or spend can look like a hijacked account, so Meta restricts it. If you increased spend on purpose, gather proof that you did: the campaign plan, the invoices and the access list. If you did not, check for unknown admins and ads, secure the account, and appeal as a suspected hack.',
 [('Check who ran the spend', 'Look at the activity history.'),
  ('Secure the account', 'Remove unknown admins, turn on two-factor.'),
  ('Appeal with context', 'Explain what changed and why.')],
 ['A big budget increase on a new or quiet account.', 'Ads you did not create.', 'A new admin or payment method added just before.', 'A login from an unusual place.'],
 ['Open the activity history and note each change.', 'Remove admins and payment methods you do not recognise.', 'Turn on two-factor for every admin.', 'Appeal, saying whether the spend was planned.'],
 [('Does the unpaid spend matter?', 'A balance owed can limit the account. Check billing.'),
  ('Do I appeal differently if I was hacked?', 'Yes. Use the compromised route and say so.'),
  ('Can I raise budgets slowly?', 'Gradual changes look more natural to the system.')],
 ['Advertisers who scaled a campaign sharply.', 'Owners who found ads they did not run.', 'Agencies managing client budgets.'])

ad('ad-account-disabled-after-chargeback-or-payment-dispute', 'Ad Account Disabled After a Payment Dispute',
 'Meta ad account disabled after a payment dispute?', 'After a payment dispute',
 'Meta ad account disabled after a disputed payment or a card dispute? What the system sees and how to resolve the billing before you appeal.',
 'A disputed payment is treated as a billing risk. Clear it first, then appeal.',
 'When a payment for ads is disputed with the card issuer, Meta can restrict the account until the billing is cleared. If the dispute was a mistake or a mismatch, contact the issuer to withdraw it and make sure the balance is paid with a working method. Then appeal, and explain the dispute plainly and briefly.',
 [('Settle the balance', 'Pay what is owed with a working method.'),
  ('Close the dispute', 'Ask the issuer to withdraw it if it was a mistake.'),
  ('Appeal after that', 'Mention what you resolved.')],
 ['A charge disputed with the card issuer.', 'A payment method that failed repeatedly.', 'A balance that stayed unpaid.', 'A card that was replaced without updating billing.'],
 ['Check Billing for the balance and the failed payments.', 'Pay with a working method and update the stored one.', 'Ask the issuer to withdraw the dispute if it was a mistake.', 'Appeal once, with the dates.'],
 [('Does an unpaid balance block appeals?', 'It can. Clear it first.'),
  ('What if someone else used the card?', 'Report it to the issuer and secure the account.'),
  ('Will Meta reverse the charge?', 'That is a billing matter. We help with the account review.')],
 ['Advertisers with failed or disputed payments.', 'Owners who changed cards.', 'Agencies billing clients through one account.'])

ad('ad-account-restricted-after-page-name-change', 'Ad Account Restricted After a Facebook Page Name Change',
 'Meta ad account restricted after a Page name change?', 'After a Page name change',
 'Meta ad account restricted after you changed your Facebook Page name or branding? Why it flags and how to prepare an appeal.',
 'A new Page name with the same ads can look like an attempt to avoid a previous rejection.',
 'Changing a Page name, especially while ads run, can trigger a review because it looks like a different business is using the account. Make sure the new name matches your business, website and policy pages, and gather proof of the change. Then appeal and describe the rebrand in a sentence or two.',
 [('Match the new name everywhere', 'Page, site, ads and portfolio.'),
  ('Keep proof of the rebrand', 'Registration or announcement.'),
  ('Do not change it again', 'Repeated changes look worse.')],
 ['A Page rename shortly after ad rejections.', 'A name that differs from the website and portfolio.', 'A new category on the Page.', 'Old ads still showing the previous name.'],
 ['Update the website and portfolio to match the Page.', 'Gather proof of the change.', 'Review the ads for the old name.', 'Appeal once, naming the rebrand.'],
 [('Was the rename the cause?', 'Possibly. The notice names the policy, which helps tell.'),
  ('Should I revert the name?', 'Only if the rebrand was a mistake.'),
  ('Does this affect other Pages in the portfolio?', 'Sometimes. Check each one.')],
 ['Brands that rebranded.', 'Agencies that moved a Page between clients.', 'Owners who renamed a Page for a new product.'])

ad('ad-account-restricted-after-agency-shared-access', 'Ad Account Restricted After Sharing Access With an Agency',
 'Meta ad account restricted after you shared access with an agency?', 'After sharing access with an agency',
 'Meta ad account restricted after you gave an agency or freelancer access? Why new logins raise flags and how to appeal safely.',
 'New people, new places and new devices logging in can look like a takeover.',
 'When an agency or freelancer is added to an ad account, logins from new places and devices can trigger a security review. Check who has access, make sure each person uses their own login and not a shared one, keep the roles tight, and then appeal. Explain who you added, why and when.',
 [('Use individual logins', 'No shared passwords.'),
  ('Give the least access needed', 'Advertiser, not admin, where possible.'),
  ('Explain the change', 'Who, why and when.')],
 ['Several logins from different countries in a short time.', 'A shared login used by more than one person.', 'An admin added just before the restriction.', 'Ads created in bulk by a new user.'],
 ['List everyone with access and their role.', 'Remove shared logins and reduce roles.', 'Ask each person to use their own account with two-factor.', 'Appeal with a short note about the new access.'],
 [('Is it safer to use a business portfolio?', 'Yes. Access is clearer and easier to manage.'),
  ('Can an agency appeal for me?', 'The account owner should lead, with the agency supporting.'),
  ('What if I do not know who added someone?', 'Check activity history and treat it as a security issue.')],
 ['Advertisers who hired help.', 'Agencies onboarding clients.', 'Freelance media buyers.'])

ad('ad-account-appeal-form-keeps-erroring', 'Ad Account Appeal Form Keeps Erroring',
 'Meta ad account appeal form keeps showing an error?', 'Appeal form keeps erroring',
 'Meta ad account appeal form will not submit, loops or shows an error? Common causes and what to try before you give up.',
 'Appeal forms fail for reasons that are usually in the browser, the account or the notice type.',
 'If the appeal form will not submit, try these in order: use a different browser with no extensions, log in from the usual device and place, check whether the notice offers a different appeal type, and make sure you are logged into the right profile and portfolio. If nothing works, send us a screenshot of the exact error.',
 [('Change the browser', 'No extensions and no VPN.'),
  ('Check the profile', 'Use the profile that owns the portfolio.'),
  ('Check the notice type', 'Some offer a different form.')],
 ['A browser extension blocking the form.', 'Logged in as a profile with no rights.', 'A VPN or a new device.', 'The notice type does not offer an appeal.'],
 ['Try a different browser with no extensions and no VPN.', 'Log in on your usual device and network.', 'Open Account Quality from the owner profile.', 'Screenshot the exact error and send it to us if it persists.'],
 [('Can I appeal twice?', 'Avoid sending several. Fix the problem with the form first.'),
  ('Does a missing button mean no appeal?', 'Some notices do not offer one. Check the notice text.'),
  ('Could it be a bug?', 'Yes. Forms fail sometimes. Retry later and keep a screenshot.')],
 ['Owners who cannot submit an appeal.', 'Agencies stuck on a client account.', 'Advertisers who see a blank form.'])
